mapper.select:
SELECT
    DATE(trade_at) as tradeDate,
    MAX(CASE WHEN trade_type = 'BUY'  THEN 1 ELSE 0 END) = 1 as hasBuy,
    MAX(CASE WHEN trade_type = 'SELL' THEN 1 ELSE 0 END) = 1 as hasSell
FROM trade
WHERE user_id = #{userId}
  AND YEAR(trade_at)  = #{year}
  AND MONTH(trade_at) = #{month}
GROUP BY DATE(trade_at)
ORDER BY DATE(trade_at)
